      setColumnsDialogTarget(null);
      if (!target) return;
      // A text box's or a shape's words (Format Shape > Text Box > Columns...).
      const liveSlides = slidesRef.current;
      const liveIndex = activeIndexRef.current;
      const liveSlide = liveSlides[liveIndex];
      const blockIndex = liveSlide
        ? liveSlide.blocks.findIndex((block) => block.id === target.blockId)
        : -1;
      const block = blockIndex >= 0 ? liveSlide.blocks[blockIndex] : null;
