      // bare Cmd/Ctrl is what PowerPoint binds these five actions to.
      if (event.altKey || event.shiftKey) return;
      const root = rootRef.current;
      const active = document.activeElement;
      // Focus must be inside this editor, and NOT on a live text-editing surface
      // (the edit guard). Otherwise let the browser / another handler have the key.
      if (!nativeOfficeOwnsFocus(root, active)) return;
      if (isTextEditTarget(active)) return;
