  /** Put the converted diagram exactly where the native one sat in z-order. */
  const slideWithConvertedSmartArt = useCallback(
    (
      slide: SlideModel,
      view: NativeSmartArtView,
      converted: readonly PresentationBlock[],
    ): SlideModel | null => {
      const members = new Set(view.members.map((block) => block.id));
      const position = slide.blocks.findIndex((block) => members.has(block.id));
      const remaining = slide.blocks.filter((block) => !members.has(block.id));
      if (
        position < 0 ||
        remaining.length + converted.length > MAX_PRESENTATION_BLOCKS_PER_SLIDE
      ) {
        return null;
      }
      // The converted diagram states no place of its own, so it paints where
      // the list puts it: at the place its preserved members stated, not at
      // their spot in the list (the importer lists them last).
      const place = presentationFirstStatedPlace(view.members);
      const at =
        place === null
          ? position
          : presentationListIndexForPlace(remaining, place, {
              reordered: presentationSlideReordersNativeObjects(slide),
            });
      return {
        ...slide,
        blocks: [
          ...remaining.slice(0, at),
          ...converted,
          ...remaining.slice(at),
        ],
      };
    },
    [],
  );

  








